INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-001', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '函数的定义域', '函数 \\( f(x)=\\sqrt{x-1}+\\ln x \\) 的定义域为（ ）', '["\\\\( (0,1] \\\\)","\\\\( [1,+\\\\infty) \\\\)","\\\\( (1,+\\\\infty) \\\\)","\\\\( (-\\\\infty,+\\\\infty) \\\\)"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '需满足 \\( x-1\\ge 0 \\) 且 \\( x>0 \\)，故 \\( x\\ge 1 \\)。', NULL, NULL, NULL, 2, '["函数"]'::jsonb, '高等数学（第六版）', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-006', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '极限的定义', '\\( \\displaystyle \\lim_{x\\to x_0} f(x)=A \\) 的 \\( \\varepsilon\\!-\\!\\delta \\) 定义中，\\( \\delta \\) 与 \\( \\varepsilon \\) 的关系是（ ）', '["\\\\( \\\\delta \\\\) 与 \\\\( \\\\varepsilon \\\\) 无关","\\\\( \\\\delta \\\\) 唯一确定","\\\\( \\\\delta \\\\) 依赖于 \\\\( \\\\varepsilon \\\\)","\\\\( \\\\varepsilon \\\\) 依赖于 \\\\( \\\\delta \\\\)"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( \\delta \\) 依赖于 \\( \\varepsilon \\)，且一般随 \\( \\varepsilon \\) 变小而变小。', NULL, NULL, NULL, 2, '["函数极限"]'::jsonb, '高等数学（第六版）', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-012', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '间断点类型', '函数 \\( f(x)=\\frac{\\sin x}{x} \\) 在 \\( x=0 \\) 处的间断点属于（ ）', '["可去间断点","跳跃间断点","无穷间断点","振荡间断点"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '\\( \\lim_{x\\to0}\\frac{\\sin x}{x}=1 \\) 存在但函数在该点无定义，为可去间断点。', NULL, NULL, NULL, 2, '["连续性"]'::jsonb, '高等数学（第六版）', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-016', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '小测：极限存在', '下列极限存在的是（ ）', '["\\\\( \\\\displaystyle\\\\lim_{x\\\\to0}\\\\frac{1}{x} \\\\)","\\\\( \\\\displaystyle\\\\lim_{x\\\\to0}\\\\frac{x}{x} \\\\)","\\\\( \\\\displaystyle\\\\lim_{x\\\\to0}\\\\sin\\\\frac{1}{x} \\\\)","\\\\( \\\\displaystyle\\\\lim_{x\\\\to\\\\infty}\\\\sin x \\\\)"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '\\( \\lim_{x\\to0}\\frac{x}{x}=1 \\) 存在；其余分别为 \\( \\infty \\) 或不存在。', NULL, NULL, NULL, 2, '["极限"]'::jsonb, '高等数学（第六版）', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m2-002', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '导数的几何意义', '函数 \\( y=f(x) \\) 在 \\( x_0 \\) 处的导数 \\( f^{\\prime}(x_0) \\) 表示曲线在该点处（ ）', '["切线的斜率","法线的斜率","割线的斜率","曲率"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '导数为切线斜率。', NULL, NULL, NULL, 2, '["导数"]'::jsonb, '高等数学（第六版）', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m3-011', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '小测：中值定理', '下列函数在 \\( [-1,1] \\) 上满足罗尔定理条件的是（ ）', '["\\\\( x \\\\)","\\\\( |x| \\\\)","\\\\( 1-x^2 \\\\)","\\\\( \\\\frac{1}{x} \\\\)"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( f(x)=1-x^2 \\) 在端点值相等且可导。', NULL, NULL, NULL, 2, '["中值定理"]'::jsonb, '高等数学（第六版）', 5) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m4-007', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '小测：原函数', '下列哪一个是 \\( x^2 \\) 的原函数（ ）', '["\\\\( x^3 \\\\)","\\\\( \\\\frac{x^3}{3} \\\\)","\\\\( 2x \\\\)","\\\\( \\\\frac{x^3}{3}+1 \\\\)"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '\\( \\left(\\frac{x^3}{3}\\right)^{\\prime}=x^2 \\)。', NULL, NULL, NULL, 2, '["不定积分"]'::jsonb, '高等数学（第六版）', 6) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m5-007', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '小测：积分中值定理', '积分中值定理中的 \\( \\xi \\) 满足（ ）', '["\\\\( \\\\xi\\\\in[a,b] \\\\)","\\\\( \\\\xi\\\\in(a,b) \\\\)","\\\\( \\\\xi=a \\\\)","\\\\( \\\\xi=b \\\\)"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '\\( \\xi\\in[a,b] \\)。', NULL, NULL, NULL, 2, '["定积分"]'::jsonb, '高等数学（第六版）', 7) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m6-005', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '小测：面积元素', '由 \\( y=f(x)\\ge0 \\)、\\( x=a \\)、\\( x=b \\) 与 \\( x \\) 轴围成的曲边梯形面积为（ ）', '["\\\\( \\\\displaystyle\\\\int_a^b f(x)\\\\,dx \\\\)","\\\\( \\\\displaystyle\\\\int_a^b f^{\\\\prime}(x)\\\\,dx \\\\)","\\\\( \\\\displaystyle\\\\int_b^a f(x)\\\\,dx \\\\)","\\\\( f(b)-f(a) \\\\)"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '面积为 \\( \\int_a^b f(x)\\,dx \\)。', NULL, NULL, NULL, 2, '["面积"]'::jsonb, '高等数学（第六版）', 8) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m7-007', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-0', 0, '总复习：核心概念', '下列等式正确的是（ ）', '["\\\\( \\\\frac{d}{dx}\\\\int f(x)\\\\,dx=f(x)+C \\\\)","\\\\( \\\\int f^{\\\\prime}(x)\\\\,dx=f^{\\\\prime}(x)+C \\\\)","\\\\( \\\\int f^{\\\\prime}(x)\\\\,dx=f(x)+C \\\\)","\\\\( \\\\int_a^b f(x)\\\\,dx=f(b)-f(a) \\\\)"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( \\int f^{\\prime}(x)\\,dx=f(x)+C \\)。', NULL, NULL, NULL, 2, '["总复习"]'::jsonb, '高等数学（第六版）', 9) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-1-final-sec-1', 'exam-calculus-1-final', '二、填空题', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-002', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-1', 2, '函数的复合', '若 \\( f(x)=x^2 \\)，则 \\( f(x+1)=\\) __________。', '[]'::jsonb, 'x^2+2x+1', '[]'::jsonb, NULL, NULL, NULL, '代入得 \\( (x+1)^2=x^2+2x+1 \\)。', NULL, NULL, NULL, 2, '["函数"]'::jsonb, '高等数学（第六版）', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-009', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-1', 2, '重要极限', '\\( \\displaystyle \\lim_{x\\to\\infty}\\left(1+\\frac{1}{x}\\right)^x=\\) __________。', '[]'::jsonb, 'e', '[]'::jsonb, NULL, NULL, NULL, '第二个重要极限。', NULL, NULL, NULL, 2, '["重要极限"]'::jsonb, '高等数学（第六版）', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-011', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-1', 2, '无穷小的比较', '当 \\( x\\to 0 \\) 时，\\( 1-\\cos x \\) 与 \\( x^2 \\) 是__________无穷小（填“同阶”“等价”或“高阶”）。', '[]'::jsonb, '同阶', '[]'::jsonb, NULL, NULL, NULL, '\\( 1-\\cos x\\sim \\frac{1}{2}x^2 \\)，故为同阶非等价。', NULL, NULL, NULL, 2, '["无穷小"]'::jsonb, '高等数学（第六版）', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-013', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-1', 2, '闭区间连续函数性质', '若 \\( f(x) \\) 在 \\( [0,1] \\) 上连续，且 \\( f(0)<0<f(1) \\)，则至少存在一点 \\( \\xi\\in \\) __________ 使得 \\( f(\\xi)=0 \\)。', '[]'::jsonb, '(0,1)', '[]'::jsonb, NULL, NULL, NULL, '零点定理。', NULL, NULL, NULL, 2, '["连续性"]'::jsonb, '高等数学（第六版）', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m2-008', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-1', 2, '微分的定义', '若 \\( y=f(x) \\) 可微，则 \\( dy=\\) __________。', '[]'::jsonb, 'f(x)dx', '[]'::jsonb, NULL, NULL, NULL, '微分 \\( dy=f^{\\prime}(x)\\,dx \\)。', NULL, NULL, NULL, 2, '["微分"]'::jsonb, '高等数学（第六版）', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m3-001', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-1', 2, '罗尔定理条件', '罗尔定理要求函数在闭区间 [a,b] 上连续，在开区间 (a,b) 内可导，且端点函数值 __________。', '[]'::jsonb, '相等', '[]'::jsonb, NULL, NULL, NULL, '罗尔定理要求函数在端点处函数值相等。', NULL, NULL, NULL, 2, '["中值定理"]'::jsonb, '高等数学（第六版）', 5) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
