INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m1-017', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-3', 3, '小测：数列极限', '求 \\( \\displaystyle \\lim_{n\\to\\infty}\\left(\\frac{1}{2}\\right)^n \\)。', '[]'::jsonb, '0', '[]'::jsonb, NULL, 0.000001, NULL, '公比绝对值小于 1 的几何数列极限为 0。', NULL, NULL, NULL, 2, '["数列极限"]'::jsonb, '高等数学（第六版）', 6) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m2-001', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-3', 3, '用定义求导数', '设 \\( f(x)=x^2 \\)，用导数定义求 \\( f^{\\prime}(1) \\)。', '[]'::jsonb, '2', '[]'::jsonb, NULL, 0.000001, NULL, '\\( \\lim_{h\\to0}\\frac{(1+h)^2-1}{h}=\\lim_{h\\to0}(2+h)=2 \\)。', NULL, NULL, NULL, 2, '["导数"]'::jsonb, '高等数学（第六版）', 7) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m2-003', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-3', 3, '基本求导', '求 \\( y=x^3-2x^2+5x-1 \\) 的导数 \\( y^{\\prime} \\)。', '[]'::jsonb, '3x^2-4x+5', '[]'::jsonb, NULL, NULL, NULL, '逐项求导。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）', 8) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m2-004', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-3', 3, '乘积法则', '求 \\( y=x^2\\sin x \\) 的导数 \\( y^{\\prime} \\)。', '[]'::jsonb, '2xsinx+x^2cosx', '[]'::jsonb, NULL, NULL, NULL, '乘积法则：\\( (x^2)^{\\prime}\\sin x+x^2(\\sin x)^{\\prime} \\)。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）', 9) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m2-005', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-3', 3, '商的求导', '求 \\( y=\\frac{e^x}{x} \\) 的导数 \\( y^{\\prime} \\)。', '[]'::jsonb, '(e^x*x-e^x)/x^2', '[]'::jsonb, NULL, NULL, NULL, '商的法则：\\( \\frac{e^x\\cdot x-e^x\\cdot1}{x^2} \\)。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）', 10) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m2-006', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-3', 3, '二阶导数', '设 \\( y=\\sin x \\)，求 \\( y^{\\prime\\prime} \\)。', '[]'::jsonb, '-sinx', '[]'::jsonb, NULL, NULL, NULL, '\\( y^{\\prime}=\\cos x \\)，\\( y^{\\prime\\prime}=-\\sin x \\)。', NULL, NULL, NULL, 2, '["高阶导数"]'::jsonb, '高等数学（第六版）', 11) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-1-final-sec-4', 'exam-calculus-1-final', '五、证明题', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m3-002', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-4', 4, '拉格朗日中值定理应用', '证明：当 \\( x>0 \\) 时，\\( \\ln(1+x)<x \\)。', '[]'::jsonb, '见解析', '[]'::jsonb, NULL, NULL, NULL, '设 \\( f(t)=\\ln(1+t) \\)，在 \\( [0,x] \\) 上用拉格朗日中值定理：\\( \\frac{\\ln(1+x)-\\ln1}{x}=\\frac{1}{1+\\xi}<1 \\)，其中 \\( 0<\\xi<x \\)，故 \\( \\ln(1+x)<x \\)。', NULL, NULL, NULL, 2, '["中值定理"]'::jsonb, '高等数学（第六版）', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-1-final-sec-5', 'exam-calculus-1-final', '六、多选题', 5) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-calculus-1-c1-m2-011', 'exam-calculus-1-final', 'exam-calculus-1-final-sec-5', 1, '小测：求导法则', '下列求导正确的是（ ）', '["A. \\\\( (\\\\sin x)^{\\\\prime}=\\\\cos x \\\\)","B. \\\\( (\\\\cos x)^{\\\\prime}=\\\\sin x \\\\)","C. \\\\( (e^x)^{\\\\prime}=e^x \\\\)","D. \\\\( (x^3)^{\\\\prime}=2x^2 \\\\)"]'::jsonb, '[''0'', ''2'']', '[]'::jsonb, NULL, NULL, NULL, 'A: \\( (\\sin x)^{\\prime}=\\cos x \\) 对；C: \\( (e^x)^{\\prime}=e^x \\) 对。', NULL, NULL, NULL, 2, '["求导法则"]'::jsonb, '高等数学（第六版）', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
